// === Tab: Spore ===
class Spore {
	constructor(pos, id) {
		this.pos = createVector(pos.x, 0, pos.y);
		this.ang = createVector(random(-PI / 16, PI / 16), 0, random(-PI / 16, PI / 16));
		this.r = 0;
		this.rv = random(0.1, 0.3);
		this.len = 0;
		this.lv = random(0.1, 0.3);
		this.maxlen = 40 - sin(map(this.pos.mag(), 0, 300, 0, HALF_PI)) * 10;
		this.maxr = random(40, 60);
		this.base = random(355)
		this.f = random(140, 180);
		this.id = id;
		this.d = this.pos.mag();
		this.type = random([0, 1, 2]);
	}
	show() {
		push();
		translate(this.pos);
		specularMaterial(0);
		fill(this.base);
		let dim = max(2, this.r / 3);
		ellipsoid(dim, dim / 8, dim);
		let xtilt = 0.5 - noise(this.d / 10, frameCount / 1000);
		let ztilt = 0.5 - noise(this.d / 10, frameCount / 1000);
		fill(255, 150);
		specularMaterial(255);
		for (let i = 0; i < 3; i++) {
			rotateX(this.ang.x + xtilt);
			rotateZ(this.ang.z + ztilt);
			translate(0, -this.len / 2, 0);
			cylinder(0.5, this.len);
			translate(0, -this.len / 2, 0);
		}
		specularMaterial(0);
		fill(this.f, this.f, this.f / 2);
		noStroke();
		sphere(this.len / 10);
		pop();
		if (frameCount > this.id && this.r < this.maxr) this.r += this.rv;
		if (frameCount > 2 * this.id && this.len < this.maxlen) this.len += this.lv;
		if (this.len > this.maxlen) {
			if (this.type == 0) this.f *= 0.99
			else if (this.type == 1) this.f *= 1.1
		}
	}
}

// === Tab: mySketch ===
// For genuary2026, day 27, theme: "lifeform". 
// I originally drafted this For the #WCCChallenge, theme: "petri dish".
// But then went with a 2D version instead.
// Inspired by this amazing short YouTube film: 
// "The Rise of Molds" https://www.youtube.com/watch?v=IQ8Br_sUfI8

let spores = [];
const maxnum = 500;
let r = 0;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);	
}

function draw() {
	background(255);
	ambientLight(100);
	pointLight(100, 100, 100, -600, 200, 300);
	orbitControl();
	rotateX(-PI / 8);
	noStroke();
	for (let s of spores) {
		s.show();
	}
	noStroke();
	fill(255, 50);
	translate(0, -22, 0);
	specularMaterial(255, 10);
	cylinder(320, 50, 64, 1, false, true);
	if(frameCount<90) return;
	for (let i = 0; i < 5; i++) {
		let pos = p5.Vector.random2D().mult(r);
		let s = new Spore(pos, 1.25*frameCount);
		if (spores.length < maxnum) {
			spores.push(s);
			r += 0.45;
		}
	}
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
